    public function __construct(protected array $settings = [], ?string $class_name = null)
    {
        if ($class_name) {
            $this->class_name = $class_name;
        }
    }
    public function get_class_name(): string
    {
        return $this->class_name;
    }
    public function set_class_name(string $class_name): self
    {
        $this->class_name = $class_name;
        return $this;
    }
    public function class_name(?string $class_name = null): self|string
    {
        return $class_name === null ? $this->get_class_name() : $this->set_class_name($class_name);
    }
    public function get_settings(): array
    {
        return $this->settings;
    }
    public function set_settings(array $settings): self
    {
        $this->settings = $settings;
        return $this;
    }
    public function settings(?array $settings = null): self|array
    {
        return $settings === null ? $this->get_settings() : $this->set_settings($settings);
    }
    public function merge_settings(array $settings): self
    {
        $this->settings = array_merge($this->settings, $settings);
        return $this;
    }
    public function set_human_diff_options(int $human_diff_options): void
    {
        $this->merge_settings(['humanDiffOptions' => $human_diff_options]);
    }
    public function enable_human_diff_option($human_diff_option): void
    {
        $this->set_human_diff_options($this->get_human_diff_options() | $human_diff_option);
    }
    public function disable_human_diff_option(int $human_diff_option): void
    {
        $this->set_human_diff_options($this->get_human_diff_options() & ~$human_diff_option);
    }
    public function get_human_diff_options(): int
    {
        return (int) ($this->get_settings()['humanDiffOptions'] ?? 0);
    }
    /**
     * Register a custom macro.
     *
     * Pass null macro to remove it.
     *
     * @example
     * ```
     * $userSettings = [
     *   'locale' => 'pt',
     *   'timezone' => 'America/Sao_Paulo',
     * ];
     * $factory->macro('userFormat', function () use ($userSettings) {
     *   return $this->copy()->locale($userSettings['locale'])->tz($userSettings['timezone'])->calendar();
     * });
     * echo $factory->yesterday()->hours(11)->userFormat();
     * ```
     *
     * @param-closure-this  static  $macro
     */
    public function macro(string $name, ?callable $macro): void
    {
        $macros = $this->get_settings()['macros'] ?? [];
        $macros[$name] = $macro;
        $this->merge_settings(['macros' => $macros]);
    }
    /**
     * Remove all macros and generic macros.
     */
    public function reset_macros(): void
    {
        $this->merge_settings(['macros' => null, 'genericMacros' => null]);
    }
    /**
     * Register a custom macro.
     *
     * @param int      $priority marco with higher priority is tried first
     *
     */
    public function generic_macro(callable $macro, int $priority = 0): void
    {
        $generic_macros = $this->get_settings()['genericMacros'] ?? [];
        if (!isset($generic_macros[$priority])) {
            $generic_macros[$priority] = [];
            krsort($generic_macros, SORT_NUMERIC);
        }
        $generic_macros[$priority][] = $macro;
        $this->merge_settings(['genericMacros' => $generic_macros]);
    }
    /**
     * Checks if macro is registered globally.
     */
    public function has_macro(string $name): bool
    {
        return isset($this->get_settings()['macros'][$name]);
    }
    /**
     * Get the raw callable macro registered globally for a given name.
     */
    public function get_macro(string $name): ?callable
    {
        return $this->get_settings()['macros'][$name] ?? null;
    }
    /**
     * Set the default translator instance to use.
     */
    public function set_translator(Translator_Interface $translator): void
    {
        $this->translator = $translator;
    }
    /**
     * Initialize the default translator instance if necessary.
     */
    public function get_translator(): Translator_Interface
    {
        return $this->translator ??= Translator::get();
    }
