        $this->merge_settings(['toJsonFormat' => $format]);
    }
    /**
     * Enable the strict mode (or disable with passing false).
     */
    public function use_strict_mode(bool $strict_mode_enabled = true): void
    {
        $this->merge_settings(['strictMode' => $strict_mode_enabled]);
    }
    /**
     * Returns true if the strict mode is globally in use, false else.
     * (It can be overridden in specific instances.)
     */
    public function is_strict_mode_enabled(): bool
    {
        return $this->get_settings()['strictMode'] ?? true;
    }
    /**
     * Indicates if months should be calculated with overflow.
     */
    public function use_months_overflow(bool $months_overflow = true): void
    {
        $this->merge_settings(['monthOverflow' => $months_overflow]);
    }
    /**
     * Reset the month overflow behavior.
     */
    public function reset_months_overflow(): void
    {
        $this->use_months_overflow();
    }
    /**
     * Get the month overflow global behavior (can be overridden in specific instances).
     */
    public function should_overflow_months(): bool
    {
        return $this->get_settings()['monthOverflow'] ?? true;
    }
    /**
     * Indicates if years should be calculated with overflow.
     */
    public function use_years_overflow(bool $years_overflow = true): void
    {
        $this->merge_settings(['yearOverflow' => $years_overflow]);
    }
    /**
     * Reset the month overflow behavior.
     */
    public function reset_years_overflow(): void
    {
        $this->use_years_overflow();
    }
    /**
     * Get the month overflow global behavior (can be overridden in specific instances).
     */
    public function should_overflow_years(): bool
    {
        return $this->get_settings()['yearOverflow'] ?? true;
    }
    /**
     * Get weekend days
     */
    public function get_weekend_days(): array
    {
        return $this->weekend_days;
    }
    /**
     * Set weekend days
     */
    public function set_weekend_days(array $days): void
    {
        $this->weekend_days = $days;
    }
    /**
     * Checks if the (date)time string is in a given format.
     *
     * @example
     * ```
     * Carbon::hasFormat('11:12:45', 'h:i:s'); // true
     * Carbon::hasFormat('13:12:45', 'h:i:s'); // false
     * ```
     */
    public function has_format(string $date, string $format): bool
    {
        // createFromFormat() is known to handle edge cases silently.
        // E.g. "1975-5-1" (Y-n-j) will still be parsed correctly when "Y-m-d" is supplied as the format.
        // To ensure we're really testing against our desired format, perform an additional regex validation.
        return $this->match_format_pattern($date, preg_quote($format, '/'), $this->regex_formats);
    }
    /**
     * Checks if the (date)time string is in a given format.
     *
     * @example
     * ```
     * Carbon::hasFormatWithModifiers('31/08/2015', 'd#m#Y'); // true
     * Carbon::hasFormatWithModifiers('31/08/2015', 'm#d#Y'); // false
     * ```
     */
    public function has_format_with_modifiers(string $date, string $format): bool
    {
        return $this->match_format_pattern($date, $format, array_merge($this->regex_formats, $this->regex_format_modifiers));
    }
    /**
     * Set a Carbon instance (real or mock) to be returned when a "now"
     * instance is created.  The provided instance will be returned
     * specifically under the following conditions:
     *   - A call to the static now() method, ex. Carbon::now()
     *   - When a null (or blank string) is passed to the constructor or parse(), ex. new Carbon(null)
     *   - When the string "now" is passed to the constructor or parse(), ex. new Carbon('now')
     *   - When a string containing the desired time is passed to Carbon::parse().
     *
     * Note the timezone parameter was left out of the examples above and
     * has no affect as the mock value will be returned regardless of its value.
     *
     * Only the moment is mocked with setTestNow(), the timezone will still be the one passed
     * as parameter of date_default_timezone_get() as a fallback (see setTestNowAndTimezone()).
     *
     * To clear the test instance call this method using the default
     * parameter of null.
     *
     * /!\ Use this method for unit tests only.
     *
     * @param DateTimeInterface|Closure|static|string|false|null $testNow real or mock Carbon instance
     */
    public function set_test_now(mixed $test_now = null): void
    {
        $this->use_timezone_from_test_now = false;
        $this->test_now = $test_now instanceof self || $test_now instanceof Closure ? $test_now : $this->make($test_now);
    }
    /**
     * Set a Carbon instance (real or mock) to be returned when a "now"
     * instance is created.  The provided instance will be returned
     * specifically under the following conditions:
     *   - A call to the static now() method, ex. Carbon::now()
     *   - When a null (or blank string) is passed to the constructor or parse(), ex. new Carbon(null)
     *   - When the string "now" is passed to the constructor or parse(), ex. new Carbon('now')
     *   - When a string containing the desired time is passed to Carbon::parse().
     *
     * It will also align default timezone (e.g. call date_default_timezone_set()) with
     * the second argument or if null, with the timezone of the given date object.
     *
     * To clear the test instance call this method using the default
     * parameter of null.
     *
     * /!\ Use this method for unit tests only.
     *
     * @param DateTimeInterface|Closure|static|string|false|null $testNow real or mock Carbon instance
     */
    public function set_test_now_and_timezone(mixed $test_now = null, $timezone = null): void
    {
        if ($test_now) {
            $this->test_default_timezone ??= date_default_timezone_get();
        }
        $use_date_instance_timezone = $test_now instanceof DateTimeInterface;
        if ($use_date_instance_timezone) {
            $this->set_default_timezone($test_now->get_timezone()->get_name(), $test_now);
        }
        $this->set_test_now($test_now);
        $this->use_timezone_from_test_now = $timezone === null && $test_now instanceof Closure;
        if (!$use_date_instance_timezone) {
            $now = $this->get_mocked_test_now(\func_num_args() === 1 ? null : $timezone);
            $this->set_default_timezone($now?->tz_name ?? $this->test_default_timezone ?? 'UTC', $now);
        }
        if (!$test_now) {
            $this->test_default_timezone = null;
        }
    }
    /**
     * Temporarily sets a static date to be used within the callback.
     * Using setTestNow to set the date, executing the callback, then
     * clearing the test instance.
     *
     * /!\ Use this method for unit tests only.
     *
     * @template T
     *
     * @param DateTimeInterface|Closure|static|string|false|null $testNow  real or mock Carbon instance
     * @param Closure(): T                                       $callback
     *
     * @return T
     */
    public function with_test_now(mixed $test_now, callable $callback): mixed
    {
        $previous_test_now = $this->get_test_now();
        $this->set_test_now($test_now);
        try {
            $result = $callback();
        } finally {
            $this->set_test_now($previous_test_now);
        }
        return $result;
    }
    /**
     * Get the Carbon instance (real or mock) to be returned when a "now"
     * instance is created.
     *
     * @return Closure|CarbonInterface|null the current instance used for testing
     */
    public function get_test_now(): Closure|Carbon_Interface|null
    {
        if ($this->test_now === null) {
            $factory = Factory_Immutable::get_default_instance();
            if ($factory !== $this) {
                return $factory->get_test_now();
            }
        }
        return $this->test_now;
    }
    public function handle_test_now_closure(Closure|Carbon_Interface|null $test_now, DateTimeZone|string|int|null $timezone = null): ?Carbon_Interface
    {
        if ($test_now instanceof Closure) {
            $callback = Callback::from_closure($test_now);
            $real_now = new DateTimeImmutable('now');
            $test_now = $test_now($callback->prepare_parameter($this->parse($real_now->format('Y-m-d H:i:s.u'), $timezone ?? $real_now->get_timezone())));
            if ($test_now !== null && !$test_now instanceof DateTimeInterface) {
                $function = $callback->get_reflection_function();
                $type = get_debug_type($test_now);
                throw new RuntimeException('The test closure defined in ' . $function->get_file_name() . ' at line ' . $function->get_start_line() . ' returned ' . $type . '; expected ' . Carbon_Interface::class . '|null');
            }
            if (!$test_now instanceof Carbon_Interface) {
                $timezone ??= $this->use_timezone_from_test_now ? $test_now->get_timezone() : null;
                $test_now = $this->__call('instance', [$test_now, $timezone]);
            }
        }
        return $test_now;
    }
    /**
     * Determine if there is a valid test instance set. A valid test instance
     * is anything that is not null.
     *
     * @return bool true if there is a test instance, otherwise false
     */
    public function has_test_now(): bool
    {
        return $this->get_test_now() !== null;
    }
    public function with_time_zone(DateTimeZone|string|int|null $timezone): static
    {
        $factory = clone $this;
        $factory->settings['timezone'] = $timezone;
        return $factory;
    }
    public function __call(string $name, array $arguments): mixed
    {
        $method = new ReflectionMethod($this->class_name, $name);
        $settings = $this->settings;
        if ($settings && isset($settings['timezone'])) {
            $timezone_parameters = array_filter($method->get_parameters(), fn(\ReflectionParameter $parameter) => \in_array($parameter->get_name(), ['tz', 'timezone'], true));
            $timezone_setting = $settings['timezone'];
            if (isset($arguments[0]) && \in_array($name, ['instance', 'make', 'create', 'parse'], true)) {
                if ($arguments[0] instanceof DateTimeInterface) {
                    $settings['innerTimezone'] = $settings['timezone'];
                } elseif (\is_string($arguments[0]) && date_parse($arguments[0])['is_localtime']) {
                    unset($settings['timezone'], $settings['innerTimezone']);
                }
            }
            if (\count($timezone_parameters)) {
                $index = key($timezone_parameters);
                if (!isset($arguments[$index])) {
                    array_splice($arguments, key($timezone_parameters), 0, [$timezone_setting]);
                }
                unset($settings['timezone']);
            }
        }
        $clock = Factory_Immutable::get_current_clock();
        Factory_Immutable::set_current_clock($this);
        try {
            $result = $this->class_name::$name(...$arguments);
        } finally {
            Factory_Immutable::set_current_clock($clock);
        }
        if (isset($this->translator)) {
            $settings['translator'] = $this->translator;
        }
        return $result instanceof Carbon_Interface && !empty($settings) ? $result->settings($settings) : $result;
    }
    /**
     * Get the mocked date passed in setTestNow() and if it's a Closure, execute it.
     */
    protected function get_mocked_test_now(DateTimeZone|string|int|null $timezone): ?Carbon_Interface
    {
        $test_now = $this->handle_test_now_closure($this->get_test_now());
        if ($test_now instanceof Carbon_Interface) {
            $test_now = $test_now->avoid_mutation();
            if ($timezone !== null) {
                return $test_now->set_timezone($timezone);
            }
        }
        return $test_now;
    }
    /**
     * Checks if the (date)time string is in a given format with
     * given list of pattern replacements.
     *
     * @example
     * ```
     * Carbon::hasFormat('11:12:45', 'h:i:s'); // true
     * Carbon::hasFormat('13:12:45', 'h:i:s'); // false
     * ```
     *
     *
     */
    private function match_format_pattern(string $date, string $format, array $replacements): bool
    {
        // Preg quote, but remove escaped backslashes since we'll deal with escaped characters in the format string.
        $regex = str_replace('\\\\', '\\', $format);
        // Replace not-escaped letters
        $regex = preg_replace_callback('/(?<!\\\\)((?:\\\\{2})*)([' . implode('', array_keys($replacements)) . '])/', static fn($match): string => $match[1] . strtr($match[2], $replacements), $regex);
        // Replace escaped letters by the letter itself
        $regex = preg_replace('/(?<!\\\\)((?:\\\\{2})*)\\\\(\w)/', '$1$2', (string) $regex);
        // Escape not escaped slashes
        $regex = preg_replace('#(?<!\\\\)((?:\\\\{2})*)/#', '$1\/', (string) $regex);
        return (bool) @preg_match('/^' . $regex . '$/', $date);
    }
    private function set_default_timezone(string $timezone, ?DateTimeInterface $date = null): void
    {
        $previous = null;
        $success = false;
        try {
            $success = date_default_timezone_set($timezone);
        } catch (Throwable $exception) {
            $previous = $exception;
        }
        if (!$success) {
            $suggestion = @Carbon_Time_Zone::create($timezone)->to_region_name($date);
            throw new InvalidArgumentException("Timezone ID '{$timezone}' is invalid" . ($suggestion && $suggestion !== $timezone ? ", did you mean '{$suggestion}'?" : '.') . "\n" . "It must be one of the IDs from DateTimeZone::listIdentifiers(),\n" . 'For the record, hours/minutes offset are relevant only for a particular moment, ' . 'but not as a default timezone.', 0, $previous);
        }
    }
}